-- Schéma initial de conception ; à compléter en migrations avant exploitation.
CREATE TABLE app_user (id uuid PRIMARY KEY, identity_subject text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE evening (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES app_user(id), draft jsonb NOT NULL, version integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE partner_order (id uuid PRIMARY KEY, evening_id uuid NOT NULL REFERENCES evening(id), user_id uuid NOT NULL REFERENCES app_user(id), idempotency_key text NOT NULL, state text NOT NULL, currency char(3) NOT NULL DEFAULT 'EUR', total_minor bigint CHECK(total_minor>=0), quote_expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,idempotency_key));
CREATE TABLE order_component (id uuid PRIMARY KEY, order_id uuid NOT NULL REFERENCES partner_order(id), kind text NOT NULL CHECK(kind IN ('ticket','restaurant','payment')), provider text NOT NULL, external_reference text, state text NOT NULL, UNIQUE(provider,external_reference));
CREATE TABLE order_transition (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, order_id uuid NOT NULL REFERENCES partner_order(id), previous_state text, next_state text NOT NULL, reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_inbox (provider text NOT NULL, event_id text NOT NULL, payload_digest text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, PRIMARY KEY(provider,event_id));
CREATE TABLE outbox (id uuid PRIMARY KEY, order_id uuid NOT NULL REFERENCES partner_order(id), task_type text NOT NULL, attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
